inPattern ::= 'from' inPatternElement (',' inPatternElement)* ('(' oclExpression ')')?;

inPatternElement ::= simpleInPatternElement;

simpleInPatternElement ::= IDENTIFIER ':' oclType ('in' IDENTIFIER (',' IDENTIFIER)*)?;

